WITH RankedPosts AS (SELECT p.Id, p.Title, p.Score, p.CreationDate, p.OwnerUserId, ROW_NUMBER() OVER (PARTITION BY p.OwnerUserId ORDER BY p.Score DESC NULLS FIRST) AS rn FROM Posts AS p WHERE p.PostTypeId = 1 AND NOT (p.Score IS NULL)), ClosedPostStats AS (SELECT ph.PostId, COUNT(*) AS CloseReasonCount, GROUP_CONCAT(CASE WHEN ph.PostHistoryTypeId = 10 THEN cr.Name END, ', ') AS CloseReasons FROM PostHistory AS ph LEFT JOIN CloseReasonTypes AS cr ON CAST(ph.Comment AS Nullable(Int32)) = cr.Id WHERE ph.PostHistoryTypeId IN (10, 11) GROUP BY ph.PostId), UserReputation AS (SELECT u.Id AS UserId, u.Reputation, u.DisplayName, COALESCE(SUM(p.Score), 0) AS TotalPostScore, COALESCE(COUNT(b.Id), 0) AS BadgeCount FROM Users AS u LEFT JOIN Posts AS p ON u.Id = p.OwnerUserId AND p.PostTypeId = 1 LEFT JOIN Badges AS b ON u.Id = b.UserId GROUP BY u.Id, u.Reputation, u.DisplayName) SELECT up.DisplayName, up.Reputation, up.TotalPostScore, cps.CloseReasonCount, cps.CloseReasons, rp.Title AS TopPostTitle, rp.Score AS TopPostScore FROM UserReputation AS up LEFT JOIN ClosedPostStats AS cps ON up.UserId = cps.PostId LEFT JOIN RankedPosts AS rp ON up.UserId = rp.OwnerUserId AND rp.rn = 1 WHERE up.Reputation > 1000 ORDER BY up.Reputation DESC NULLS FIRST, cps.CloseReasonCount DESC NULLS FIRST